#include <bits/stdc++.h>
using namespace std;
// Belady: on a miss with a full cache, evict the book whose next request is farthest.
int main(){
    int n,k; cin>>n>>k;
    vector<int> a(n);
    for(auto&x:a) cin>>x;
    vector<int> nxt(n), last(n+1, INT_MAX);
    for(int i=n-1;i>=0;i--){ nxt[i]=last[a[i]]; last[a[i]]=i; }
    set<pair<int,int>> cache;           // (next use index, book)
    vector<int> inCache(n+1, -1);       // next-use index if book is cached, else -1
    int cost=0;
    for(int i=0;i<n;i++){
        int b=a[i];
        if(inCache[b]!=-1) cache.erase({inCache[b], b});
        else{
            cost++;
            if((int)cache.size()==k){
                auto it=prev(cache.end());
                inCache[it->second]=-1;
                cache.erase(it);
            }
        }
        inCache[b]=nxt[i];
        cache.insert({nxt[i], b});
    }
    cout<<cost<<"\n";
}

