#include <bits/stdc++.h>
using namespace std;
// c = n-k internal nodes (deg>=2). Minimal leaf-diameter D = d+2 where d is the least
// value with f(d) >= c, f(2r)=1+k*r, f(2r+1)=2+k*r. Build the tree around a center.
int main(){
    long long n,k; cin>>n>>k;
    long long c=n-k, d=0;
    auto f=[&](long long d){ return d%2==0 ? 1+k*(d/2) : 2+k*((d-1)/2); };
    while(f(d)<c) d++;
    vector<pair<int,int>> E; vector<int> ends; int cur, ex=c+1;
    auto attach=[&](int x){ E.push_back({x,ex++}); };
    if(d%2==0){
        long long r=d/2, rem=c-1; cur=2;
        while(rem>0){
            long long len=min(r,rem); int prev=1;
            for(long long t=0;t<len;t++){ E.push_back({prev,cur}); prev=cur++; }
            ends.push_back(prev); rem-=len;
        }
        for(int e:ends) attach(e);
        while(ex<=n) attach(1);
    } else {
        long long r=(d-1)/2, rem=c-2; cur=3; E.push_back({1,2});
        bool hasU=false, hasV=false; int side=0;
        while(rem>0){
            long long len=min(r,rem); int prev= side? 2:1;
            (side?hasV:hasU)=true;
            for(long long t=0;t<len;t++){ E.push_back({prev,cur}); prev=cur++; }
            ends.push_back(prev); rem-=len; side^=1;
        }
        for(int e:ends) attach(e);
        if(!hasU) attach(1);
        if(!hasV) attach(2);
        while(ex<=n) attach(1);
    }
    cout<<d+2<<"\n";
    for(auto [a,b]:E) cout<<a<<" "<<b<<"\n";
}

