// Try f = number of fully solved tasks (each gives k+1 points, costs S = sum t).
// Remaining time buys cheapest extra subtasks, at most n-f extra copies per subtask type.
int main(){
    long long n,k,M; cin>>n>>k>>M;
    vector<long long> t(k);
    for(auto&x:t) cin>>x;
    sort(t.begin(),t.end());
    long long S=0; for(auto x:t) S+=x;
    long long best=0;
    for(long long f=0; f<=n; f++){
        long long R=M-f*S;
        if(R<0) break;
        long long pts=f*(k+1), cap=n-f;
        for(auto x:t){
            long long take=min(cap, R/x);
            pts+=take; R-=take*x;
        }
        best=max(best,pts);
    }
    cout<<best<<"\n";
}

