// Transshipment status depends only on the trip sequence, so each trip's fare is fixed.
// A travel card on route r saves the total fare of trips on r; buy up to k cards with saving > f.
int main(){
    int n; long long a,b,k,f; cin>>n>>a>>b>>k>>f;
    map<string,int> id; auto get=[&](const string&s){ auto it=id.find(s); if(it!=id.end()) return it->second; int v=id.size(); id[s]=v; return v; };
    string prevEnd; long long total=0;
    map<pair<int,int>,long long> save;
    for(int i=0;i<n;i++){
        string s,e; cin>>s>>e;
        long long cost = (i>0 && s==prevEnd) ? b : a;
        total+=cost; prevEnd=e;
        int x=get(s), y=get(e); if(x>y) swap(x,y);
        save[{x,y}]+=cost;
    }
    vector<long long> g; for(auto&[key,v]:save) if(v-f>0) g.push_back(v-f);
    sort(g.rbegin(),g.rend());
    for(long long i=0;i<k && i<(long long)g.size();i++) total-=g[i];
    cout<<total<<"\n";
}

