// pre[d]: min cost so all cities arrive by day d; suf[d]: min cost so all cities leave on/after day d.
// Answer = min over d of pre[d] + suf[d+k+1].
int main(){
    int n,m; long long k; cin>>n>>m>>k;
    const int MD=1000001; const long long INF=LLONG_MAX/4;
    vector<vector<pair<int,long long>>> arr(MD+1), dep(MD+1);
    for(int i=0;i<m;i++){ int d,f,t; long long c; cin>>d>>f>>t>>c;
        if(t==0) arr[d].push_back({f,c}); else dep[d].push_back({t,c}); }
    auto run=[&](vector<vector<pair<int,long long>>>& ev, vector<long long>& out, bool fwd){
        vector<long long> best(n+1,INF); int cnt=0; long long sum=0;
        for(int s=1;s<=MD;s++){ int d= fwd? s : MD+1-s;
            for(auto [c,w]:ev[d]){
                if(best[c]==INF){ best[c]=w; cnt++; sum+=w; }
                else if(w<best[c]){ sum-=best[c]-w; best[c]=w; } }
            if(cnt==n) out[d]=sum; }
    };
    vector<long long> pre(MD+2,INF), suf(MD+2,INF);
    run(arr,pre,true); run(dep,suf,false);
    long long ans=INF;
    for(long long d=1; d+k+1<=MD; d++) if(pre[d]<INF && suf[d+k+1]<INF) ans=min(ans,pre[d]+suf[d+k+1]);
    cout<<(ans>=INF? -1: ans)<<"\n";
}

