// Stage s has k[s] identical windows, FIFO. Person i finishes stage s at
// max(arrival, finish of person i-k) + t, since the k-th earlier person frees the window.
int main(){
    long long k[3], t[3]; cin>>k[0]>>k[1]>>k[2]>>t[0]>>t[1]>>t[2];
    int n; cin>>n;
    vector<long long> c(n); for(auto&x:c) cin>>x;
    vector<long long> cur=c;
    for(int s=0;s<3;s++){
        vector<long long> fin(n);
        for(int i=0;i<n;i++){
            long long st=cur[i];
            if(i>=k[s]) st=max(st, fin[i-k[s]]);
            fin[i]=st+t[s];
        }
        cur=fin;
    }
    long long ans=0;
    for(int i=0;i<n;i++) ans=max(ans, cur[i]-c[i]);
    cout<<ans<<"\n";
}

