// Maximize sum of s'_i = each s'_i <= U_i where U is the largest feasible profile:
// U_i = min(s_i+g_i, U_{i-1}+1, U_{i+1}+1) (two sweeps). Feasible iff U_i >= s_i for all i.
int main(){
    int n; cin>>n;
    vector<long long> s(n), U(n);
    for(int i=0;i<n;i++){ long long g; cin>>s[i]>>g; U[i]=s[i]+g; }
    for(int i=1;i<n;i++) U[i]=min(U[i],U[i-1]+1);
    for(int i=n-2;i>=0;i--) U[i]=min(U[i],U[i+1]+1);
    long long tot=0;
    for(int i=0;i<n;i++){
        if(U[i]<s[i]){ cout<<-1<<"\n"; return 0; }
        tot+=U[i]-s[i];
    }
    cout<<tot<<"\n";
    for(int i=0;i<n;i++) cout<<U[i]<<(i+1<n?' ':'\n');
}

