// Adjacent sums must stay fixed at every check, so the state is fixed up to a shift t:
// odd-indexed cells move by t and even-indexed by -t. Hence for even n nothing can be stolen.
// For odd n, each stolen diamond costs (n+1)/2 moves per unit; each minute must end valid,
// so per minute only floor(m/((n+1)/2)) whole units move. Odd-indexed cells cap the total.
int main(){
    long long n,m,k; cin>>n>>m>>k;
    vector<long long> a(n);
    for(auto&x:a) cin>>x;
    if(n%2==0){ cout<<0<<"\n"; return 0; }
    long long cap=LLONG_MAX;
    for(long long i=0;i<n;i+=2) cap=min(cap,a[i]);
    long long units=k*(m/((n+1)/2));   // whole units per minute, since each check must be valid
    cout<<min(cap,units)<<"\n";
}

