// Elements arrive in nondecreasing order, so the best subset is {max} plus the k smallest others.
// f(k) = (k*M - P_k)/(k+1); the first k where adding x_k stops helping is found by binary search.
int main(){
    int Q; scanf("%d",&Q);
    vector<long long> x, P(1,0);
    while(Q--){
        int type; scanf("%d",&type);
        if(type==1){
            long long v; scanf("%lld",&v);
            x.push_back(v); P.push_back(P.back()+v);
        } else {
            int m=x.size(); long long M=x[m-1];
            int lo=0, hi=m-1;
            while(lo<hi){
                int mid=(lo+hi)/2;
                if(x[mid]*(mid+1) >= M+P[mid]) hi=mid; else lo=mid+1;
            }
            long double ans=(long double)(lo*M-P[lo])/(lo+1);
            printf("%.10Lf\n", ans);
        }
    }
}

