// Change (x,d) adds x + d*|i-j| to every cell. Sum over cells = n*x + d*S_i with
// S_i = sum_j |i-j|. Pick the endpoint (max S) for d>0, the median (min S) for d<0.
int main(){
    long long n,m; cin>>n>>m;
    long long Smax=0, Smin=LLONG_MAX;
    for(long long i=1;i<=n;i++){
        long long S=(i-1)*i/2 + (n-i)*(n-i+1)/2;
        Smax=max(Smax,S); Smin=min(Smin,S);
    }
    long long tot=0;
    for(long long q=0;q<m;q++){
        long long x,d; cin>>x>>d;
        tot += n*x + (d>0 ? d*Smax : d*Smin);
    }
    printf("%.15Lf\n", (long double)tot/n);
}

