// Star from vertex 1 gives n-1 edges. Coprime pairs total sum_{j=2..n} phi(j).
// Possible iff n-1 <= m <= that total. Extra edges come from coprime pairs among 2..n.
int main(){
    long long n,m; cin>>n>>m;
    vector<int> phi(n+1); iota(phi.begin(),phi.end(),0);
    for(int i=2;i<=n;i++) if(phi[i]==i) for(int j=i;j<=n;j+=i) phi[j]-=phi[j]/i;
    long long C=0; for(int j=2;j<=n;j++) C+=phi[j];
    if(m<n-1 || m>C){ cout<<"Impossible\n"; return 0; }
    cout<<"Possible\n";
    for(int i=2;i<=n;i++) cout<<1<<" "<<i<<"\n";
    long long need=m-(n-1);
    for(int j=3;j<=n && need>0;j++)
        for(int i=2;i<j && need>0;i++)
            if(__gcd(i,j)==1){ cout<<i<<" "<<j<<"\n"; need--; }
}

