using namespace std;
// Fix T = max votes any other party may keep. Parties above T must lose their cheapest
// surplus voters; then buy the cheapest remaining voters until United has T+1 votes.
// Try every T in [0, n] and keep the minimum.
int main(){
    int n,m; cin>>n>>m;
    vector<int> p(n); vector<long long> c(n);
    for(int i=0;i<n;i++) cin>>p[i]>>c[i];
    long long best=LLONG_MAX;
    for(int T=0; T<=n; T++){
        vector<vector<long long>> by(m+1);
        for(int i=0;i<n;i++) if(p[i]!=1) by[p[i]].push_back(c[i]);
        long long cost=0; int have=0;
        for(int i=0;i<n;i++) if(p[i]==1) have++;
        vector<long long> rest;
        for(int j=2;j<=m;j++){
            sort(by[j].begin(),by[j].end());
            int cnt=by[j].size();
            int forced = max(0, cnt-T);
            for(int q=0;q<forced;q++){ cost+=by[j][q]; have++; }
            for(int q=forced;q<cnt;q++) rest.push_back(by[j][q]);
        }
        if(have<T+1){
            sort(rest.begin(),rest.end());
            for(size_t q=0; q<rest.size() && have<T+1; q++){ cost+=rest[q]; have++; }
            if(have<T+1) continue;
        }
        best=min(best,cost);
    }
    cout<<best<<"\n";
}

