// Final value = product of kept elements, with at most one element deleted.
// zeros>=2 -> 0; zeros==1 -> delete the zero only if the rest is positive, else 0 (keep zero);
// no zeros -> delete the negative with smallest |a| when the negatives count is odd.
int main(){
    int n; cin>>n;
    vector<long long> a(n);
    for(auto&x:a) cin>>x;
    int zeros=0, negs=0; int del=-1; long long bestAbs=LLONG_MAX; int minNeg=-1;
    for(int i=0;i<n;i++){
        if(a[i]==0) zeros++;
        else if(a[i]<0){ negs++; if(-a[i]<bestAbs){ bestAbs=-a[i]; minNeg=i; } }
    }
    if(zeros==0 && negs%2==1) del=minNeg;
    else if(zeros==1 && negs%2==0){ for(int i=0;i<n;i++) if(a[i]==0) del=i; }
    vector<int> idx;
    for(int i=0;i<n;i++) if(i!=del) idx.push_back(i);
    if(del!=-1) cout<<2<<" "<<del+1<<"\n";
    for(size_t i=0;i+1<idx.size();i++) cout<<1<<" "<<idx[i]+1<<" "<<idx[i+1]+1<<"\n";
}

