using namespace std;
// Skip whole passes exactly: over booths with a_i <= T the cost of one full pass is s,
// so T/s full passes buy cnt candies each. Then simulate one real pass and repeat.
int main(){
    int n; long long T; cin>>n>>T;
    vector<long long> a(n);
    for(auto&x:a) cin>>x;
    long long ans=0;
    while(true){
        long long s=0, cnt=0;
        for(int i=0;i<n;i++) if(a[i]<=T){ s+=a[i]; cnt++; }
        if(cnt==0) break;
        long long full=T/s;
        ans+=full*cnt; T-=full*s;
        for(int i=0;i<n;i++) if(a[i]<=T){ T-=a[i]; ans++; }
    }
    cout<<ans<<"\n";
}

