// With d days, the best day-order gives position j (0-based) inside its day penalty j;
// sorted descending, cup i pays i/d. Pages(d)=sum max(0,a_i - i/d), monotone in d: binary search.
int main(){
    int n; long long m; cin>>n>>m;
    vector<long long> a(n);
    for(auto&x:a) cin>>x;
    sort(a.rbegin(),a.rend());
    auto pages=[&](long long d){
        long long p=0;
        for(int i=0;i<n;i++) p+=max(0LL, a[i]-i/d);
        return p;
    };
    if(pages(n)<m){ cout<<-1<<"\n"; return 0; }
    long long lo=1, hi=n;
    while(lo<hi){ long long mid=(lo+hi)/2; if(pages(mid)>=m) hi=mid; else lo=mid+1; }
    cout<<lo<<"\n";
}

