// Station a's j-th visit from start s is at time dist(s,a)+j*n. Serve candies in
// decreasing remaining distance; the answer for start s is the max arrival time.
int main(){
    int n,m; cin>>n>>m;
    vector<vector<int>> at(n+1);
    for(int i=0;i<m;i++){ int a,b; cin>>a>>b; at[a].push_back((b-a+n)%n); }
    for(auto&v:at) sort(v.rbegin(),v.rend());
    for(int s=1;s<=n;s++){
        long long best=0;
        for(int a=1;a<=n;a++)
            for(size_t j=0;j<at[a].size();j++){
                long long t=(a-s+n)%n + (long long)j*n + at[a][j];
                best=max(best,t);
            }
        cout<<best<<(s<n?' ':'\n');
    }
}

