// Words are grouped by (vowel count, last vowel) for second words, and by vowel count for first words.
// A = pairs formed from (count,last) groups; B = pairs from leftover words by count.
// m = min(A, (A+B)/2); first pairs use leftover pairs first, then surplus second pairs.
int main(){
    int n; cin>>n;
    auto isv=[](char c){ return c=='a'||c=='e'||c=='i'||c=='o'||c=='u'; };
    vector<string> w(n); map<pair<int,char>,vector<int>> G;
    for(int i=0;i<n;i++){
        cin>>w[i]; int c=0; char lv=0;
        for(char ch:w[i]) if(isv(ch)){ c++; lv=ch; }
        G[{c,lv}].push_back(i);
    }
    vector<pair<int,int>> Spairs; vector<int> leftover;
    for(auto&[key,v]:G){
        size_t q=0;
        for(;q+1<v.size();q+=2) Spairs.push_back({v[q],v[q+1]});
        if(q<v.size()) leftover.push_back(v[q]);
    }
    map<int,vector<int>> byCnt;
    for(int x:leftover){ int c=0; for(char ch:w[x]) if(isv(ch)) c++; byCnt[c].push_back(x); }
    vector<pair<int,int>> Fpairs;
    for(auto&[c,v]:byCnt) for(size_t q=0;q+1<v.size();q+=2) Fpairs.push_back({v[q],v[q+1]});
    long long A=Spairs.size(), B=Fpairs.size();
    long long m=min(A,(A+B)/2);
    cout<<m<<"\n";
    for(long long i=0;i<m;i++){
        pair<int,int> F = i < B ? Fpairs[i] : Spairs[m + (i-B)];
        pair<int,int> S = Spairs[i];
        cout<<w[F.first]<<" "<<w[S.first]<<"\n"<<w[F.second]<<" "<<w[S.second]<<"\n";
    }
}

