// A group is calm iff every member's mask is contained in another member's mask, which forces every
// maximal mask to appear at least twice. Take all students whose mask lies under a duplicated mask.
int main(){
    int n; cin>>n;
    vector<unsigned long long> a(n); vector<long long> b(n);
    for(auto&x:a) cin>>x;
    for(auto&x:b) cin>>x;
    map<unsigned long long,int> cnt;
