    vector<unsigned long long> D;
    for(auto&[m,c]:cnt) if(c>=2) D.push_back(m);
    long long best=0;
    for(int i=0;i<n;i++){
        for(auto M:D) if((a[i]&~M)==0){ best+=b[i]; break; }
    }
    cout<<best<<"\n";
}

