// Start every day at a_i; the remaining k - sum(a) portions go to the cheapest days,
// each day taking up to b_i - a_i extra.
int main(){
    int n; long long k; cin>>n>>k;
    vector<array<long long,3>> D(n);
    long long sumA=0, sumB=0, cost=0;
    for(auto&d:D){ cin>>d[1]>>d[2]>>d[0]; }   // d = {c, a, b}
    for(auto&d:D){ sumA+=d[1]; sumB+=d[2]; cost+=d[1]*d[0]; }
    if(sumA>k || sumB<k){ cout<<-1<<"\n"; return 0; }
    sort(D.begin(),D.end());
    long long need=k-sumA;
    for(auto&d:D){
        long long take=min(need, d[2]-d[1]);
        cost+=take*d[0]; need-=take;
    }
    cout<<cost<<"\n";
}

