using namespace std;
// Bicarp (second player) wins iff the halves' known sums balance with the 9-per-? weighting:
// 2*(sumL - sumR) == 9*(qR - qL), where q* counts '?' in each half.
int main(){
    int n; string s; cin>>n>>s;
    long long sl=0, sr=0, ql=0, qr=0;
    for(int i=0;i<n;i++){
        bool left = i < n/2;
        if(s[i]=='?'){ (left? ql : qr)++; }
        else { (left? sl : sr) += s[i]-'0'; }
    }
    cout<< ((2*(sl-sr) == 9*(qr-ql)) ? "Bicarp" : "Monocarp") << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// The Manhattan-closest pair among remaining points is always balanced: any point inside
// their box is strictly closer to one of them. So take pairs in increasing distance order.
int main(){
    int n; cin>>n;
    vector<array<int,3>> p(n);
    for(auto&q:p) cin>>q[0]>>q[1]>>q[2];
    vector<array<int,3>> E; E.reserve((size_t)n*(n-1)/2);
    for(int i=0;i<n;i++) for(int j=i+1;j<n;j++){
        int d=abs(p[i][0]-p[j][0])+abs(p[i][1]-p[j][1])+abs(p[i][2]-p[j][2]);
        E.push_back({d,i,j});
    }
    sort(E.begin(),E.end());
    vector<bool> used(n,false);
    for(auto&e:E){
        int i=e[1], j=e[2];
        if(used[i]||used[j]) continue;
        used[i]=used[j]=true;
        cout<<i+1<<" "<<j+1<<"\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
// Snake (boustrophedon) order makes every chicken's cells contiguous, hence connected.
// Chicken t takes consecutive cells until it has its share of rice (R/k, +1 for the first R%k).
int main(){
    int T; cin>>T;
    const string L="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    while(T--){
        int r,c,k; cin>>r>>c>>k;
        vector<string> g(r), out(r, string(c,'?'));
        for(auto&s:g) cin>>s;
        int R=0; for(auto&s:g) for(char ch:s) R+= ch=='R';
        auto quota=[&](int t){ return R/k + (t < R%k ? 1 : 0); };
        int cur=0, got=0;
        for(int i=0;i<r;i++) for(int jj=0;jj<c;jj++){
            int j = (i%2==0) ? jj : c-1-jj;
            out[i][j]=L[cur];
            if(g[i][j]=='R' && ++got==quota(cur) && cur<k-1){ cur++; got=0; }
        }
        for(auto&s:out) cout<<s<<"\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
// Opposition (candidate n) does not win iff some candidate j has total >= opposition total.
// For each j, remove stations with the largest (opp - j) first until the kept difference is <= 0.
int main(){
    int n,m; cin>>n>>m;
    vector<vector<long long>> a(m, vector<long long>(n));
    for(auto&row:a) for(auto&x:row) cin>>x;
    int bestK=INT_MAX; vector<int> bestSet;
    for(int j=0;j<n-1;j++){
        vector<int> idx(m); iota(idx.begin(),idx.end(),0);
        auto d=[&](int i){ return a[i][n-1]-a[i][j]; };
        sort(idx.begin(),idx.end(),[&](int x,int y){ return d(x)>d(y); });
        long long s=0; for(int i=0;i<m;i++) s+=d(i);
        vector<int> rem; size_t q=0;
        while(s>0){ s-=d(idx[q]); rem.push_back(idx[q]); q++; }
        if((int)rem.size()<bestK){ bestK=rem.size(); bestSet=rem; }
    }
    cout<<bestK<<"\n";
    for(int x:bestSet) cout<<x+1<<" ";
    cout<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
// Node coordinates grow at least twice per step, so only ~60 nodes are reachable.
// Any reachable run of consecutive nodes i..j costs dist(start,i)+dist(i,j) (they lie on a monotone chain).
int main(){
    long long x0,y0,ax,ay,bx,by,xs,ys,t;
    cin>>x0>>y0>>ax>>ay>>bx>>by>>xs>>ys>>t;
    long long LX=xs+t, LY=ys+t;
    vector<pair<long long,long long>> P;
    for(long long x=x0,y=y0; x<=LX && y<=LY; ){
        P.push_back({x,y});
        x=ax*x+bx; y=ay*y+by;
    }
    int best=0, m=P.size();
    for(int i=0;i<m;i++){
        long long d0=llabs(xs-P[i].first)+llabs(ys-P[i].second);
        if(d0>t) continue;
        for(int j=0;j<m;j++){
            long long dd=llabs(P[i].first-P[j].first)+llabs(P[i].second-P[j].second);
            if(d0+dd<=t) best=max(best,abs(i-j)+1);
        }
    }
    cout<<best<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
// Walk the target value upward. At each value the pending category with the largest t
// takes it; every other pending category pays its t to move up by one.
int main(){
    int n; cin>>n;
    vector<long long> a(n), t(n);
    for(auto&x:a) cin>>x;
    for(auto&x:t) cin>>x;
    vector<int> idx(n); iota(idx.begin(),idx.end(),0);
    sort(idx.begin(),idx.end(),[&](int x,int y){ return a[x]<a[y]; });
    priority_queue<long long> pq;
    long long pending=0, ans=0, cur=0; int i=0;
    while(i<n || !pq.empty()){
        if(pq.empty()) cur=a[idx[i]];
        while(i<n && a[idx[i]]<=cur){ pq.push(t[idx[i]]); pending+=t[idx[i]]; i++; }
        pending-=pq.top(); pq.pop();
        ans+=pending;
        cur++;
    }
    cout<<ans<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// Horizontal base in row i, apex in row k: 2*area = width*|k-i| (columns symmetric).
// Per digit: best existing triangles, then per cell p: p as apex (best base elsewhere) or as base endpoint.
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n; scanf("%d",&n);
        vector<string> g(n); static char buf[2105];
        for(auto&s:g){ scanf("%s",buf); s=buf; }
        for(int d=0; d<10; d++){
            char ch='0'+d;
            vector<int> minc(n,INT_MAX), maxc(n,INT_MIN), minr(n,INT_MAX), maxr(n,INT_MIN);
            int R0=INT_MAX,R1=INT_MIN,C0=INT_MAX,C1=INT_MIN;
            for(int i=0;i<n;i++) for(int j=0;j<n;j++) if(g[i][j]==ch){
                minc[i]=min(minc[i],j); maxc[i]=max(maxc[i],j);
                minr[j]=min(minr[j],i); maxr[j]=max(maxr[j],i);
                R0=min(R0,i); R1=max(R1,i); C0=min(C0,j); C1=max(C1,j); }
            ll best=0;
            if(R0!=INT_MAX){
                vector<ll> AH(n,0), AV(n,0);
                for(int i=0;i<n;i++){
                    if(maxc[i]>=minc[i]) best=max<ll>(best,(ll)(maxc[i]-minc[i])*max(i-R0,R1-i));
                    if(maxr[i]>=minr[i]) best=max<ll>(best,(ll)(maxr[i]-minr[i])*max(i-C0,C1-i)); }
                for(int i=0;i<n;i++) for(int k=0;k<n;k++){
                    if(maxc[k]>=minc[k]) AH[i]=max<ll>(AH[i],(ll)(maxc[k]-minc[k])*abs(i-k));
                    if(maxr[k]>=minr[k]) AV[i]=max<ll>(AV[i],(ll)(maxr[k]-minr[k])*abs(i-k)); }
                for(int i=0;i<n;i++) for(int j=0;j<n;j++){
                    ll c=max(AH[i],AV[j]);
                    if(maxc[i]>=minc[i]) c=max(c,(ll)max(j-minc[i],maxc[i]-j)*max(i-R0,R1-i));
                    if(maxr[j]>=minr[j]) c=max(c,(ll)max(i-minr[j],maxr[j]-i)*max(j-C0,C1-j));
                    best=max(best,c); }
            }
            printf("%lld%c", best, d==9?'\n':' ');
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
// Wows use 1,2,4,...,2^b (each exceeds the sum so far). Ohs then use max+1 (<= sum).
// Remaining grooms repeat the current maximum (no reaction). With b=0 two 1s start the sum first.
int main(){
    int n,a,b; cin>>n>>a>>b;
    if(b==0 && a>0 && n<a+2){ cout<<-1<<"\n"; return 0; }
    vector<long long> t;
    long long M;
    if(b>0){
        t.push_back(1);
        for(int k=1;k<=b;k++) t.push_back(1LL<<k);
        M=1LL<<b;
    } else {
        t.push_back(1); t.push_back(1); M=1;
    }
    for(int i=0;i<a;i++){ M++; t.push_back(M); }
    while((int)t.size()<n) t.push_back(M);
    for(int i=0;i<n;i++) cout<<t[i]<<(i+1<n?' ':'\n');
}
